body.script:
//
(function () {
  "use strict";

  // Helper to create proper HTML elements inside an XML document
  const createEl = (tag) => document.createElementNS("http://www.w3.org/1999/xhtml", tag);

  const $ = (id) => document.getElementById(id);

  const tabstrip   = $("tabstrip");
  const newTabBtn  = $("newTab");
  const frames     = $("frames");
  const startPage  = $("start");
  const fab        = $("fab");
  const urlInput   = $("urlInput");
  const omnibox    = $("omnibox");
  const lock       = $("lock");
  const backBtn    = $("backBtn");
  const fwdBtn     = $("fwdBtn");
  const reloadBtn  = $("reloadBtn");
  const homeBtn    = $("homeBtn");
  const openBtn    = $("openBtn");
  const creditsBtn = $("creditsBtn");
  const bar        = $("bar");
  const engineSelect = $("engineSelect");
  const startForm  = $("startForm");
  const startInput = $("startInput");
  const quicklinks = $("quicklinks");

  const MAX_TABS = 12;
  const CREDITS_URL = "credits.svg";

  /* ================= search engines ================= */
  const ENGINES = {
    duckduckgo: { label: "DuckDuckGo", build: (q) => "https://duckduckgo.com/?q=" + encodeURIComponent(q) },
    bing:       { label: "Bing",       build: (q) => "https://www.bing.com/search?q=" + encodeURIComponent(q) },
    google:     { label: "Google",     build: (q) => "https://www.google.com/search?q=" + encodeURIComponent(q) },
    brave:      { label: "Brave",      build: (q) => "https://search.brave.com/search?q=" + encodeURIComponent(q) },
    mojeek:     { label: "Mojeek",     build: (q) => "https://www.mojeek.com/search?q=" + encodeURIComponent(q) },
    wikipedia:  { label: "Wikipedia",  build: (q) => "https://en.wikipedia.org/w/index.php?search=" + encodeURIComponent(q) }
  };

  Object.keys(ENGINES).forEach((key) => {
    const opt = createEl("option");
    opt.value = key;
    opt.textContent = ENGINES[key].label;
    engineSelect.appendChild(opt);
  });

  let engine = localStorage.getItem("lumenproxy.engine");
  if (!ENGINES[engine]) engine = "duckduckgo";
  engineSelect.value = engine;

  engineSelect.addEventListener("change", () => {
    engine = engineSelect.value;
    localStorage.setItem("lumenproxy.engine", engine);
  });

  /* ================= quick links ================= */
  const QUICK = [
    { label: "Example.com", url: "https://example.com" },
    { label: "Wikipedia",   url: "https://en.wikipedia.org" },
    { label: "Hacker News", url: "https://news.ycombinator.com" },
    { label: "MDN",         url: "https://developer.mozilla.org" }
  ];

  QUICK.forEach((q) => {
    const b = createEl("button");
    b.type = "button";
    b.textContent = q.label;
    b.addEventListener("click", () => navigate(activeTab(), q.url));
    quicklinks.appendChild(b);
  });

  /* ================= state ================= */
  const state = { tabs: [], activeId: null, nextId: 1 };

  const activeTab = () => state.tabs.find((t) => t.id === state.activeId) || null;

  /* ================= url helpers ================= */
  function looksLikeUrl(s) {
    if (/^[a-z][a-z0-9+.-]*:\/\//i.test(s)) return true;
    if (/^localhost(:\d+)?(\/|$)/i.test(s)) return true;
    if (/^[^\s/?#]+\.[^\s/?#]{2,}(:\d+)?([/?#].*)?$/i.test(s)) return true;
    return false;
  }

  function toUrl(input) {
    const s = (input || "").trim();
    if (!s) return null;
    if (/^(javascript|data|vbscript|file):/i.test(s)) return null;

    // Relative paths (./foo, /foo, or bare filename ending in .svg or .html)
    if (/^(\.\/|\/)/.test(s) || /^[\w-]+\.(html?|svg)$/i.test(s)) return s;

    if (looksLikeUrl(s)) {
      return /^[a-z][a-z0-9+.-]*:\/\//i.test(s) ? s : "https://" + s;
    }
    return ENGINES[engine].build(s);
  }

  function hostOf(url) {
    try { return new URL(url).hostname.replace(/^www\./, ""); }
    catch (e) {
      // relative URL like "credits.svg" or "./credits.svg"
      const file = url.split("/").pop().split("?")[0].split("#")[0];
      const name = file.replace(/\.[^.]+$/, "");
      return name ? name.charAt(0).toUpperCase() + name.slice(1) : url;
    }
  }

  /* ================= loading bar ================= */
  let loadTimer = null;

  function startLoading() {
    bar.style.transition = "none";
    bar.style.width = "0%";
    bar.style.opacity = "1";
    requestAnimationFrame(() => {
      bar.style.transition = "width 2.5s cubic-bezier(.1,.75,.3,1)";
      bar.style.width = "85%";
    });
    clearTimeout(loadTimer);
    loadTimer = setTimeout(stopLoading, 8000);
  }

  function stopLoading() {
    clearTimeout(loadTimer);
    bar.style.transition = "width .2s ease, opacity .35s ease .1s";
    bar.style.width = "100%";
    bar.style.opacity = "0";
  }

  /* ================= tab elements ================= */
  function buildTabEl(tab) {
    const el = createEl("div");
    el.className = "tab";
    el.dataset.id = String(tab.id);

    const fav = createEl("span");
    fav.className = "favicon emoji";
    fav.textContent = "🌐";

    const title = createEl("span");
    title.className = "title";
    title.textContent = "New Tab";

    const close = createEl("button");
    close.className = "close";
    close.type = "button";
    close.textContent = "×";
    close.title = "Close tab";
    close.setAttribute("aria-label", "Close tab");

    el.append(fav, title, close);

    el.addEventListener("click", (e) => {
      if (e.target.closest(".close")) return;
      activateTab(tab.id);
    });

    close.addEventListener("click", (e) => {
      e.stopPropagation();
      closeTab(tab.id);
    });

    tabstrip.insertBefore(el, newTabBtn);
    tab.el = el;
  }

  function updateTabEl(tab) {
    if (!tab.el) return;
    const titleEl = tab.el.querySelector(".title");
    const favEl   = tab.el.querySelector(".favicon");

    titleEl.textContent = tab.title;
    titleEl.title = tab.url || "";

    if (tab.url) {
      favEl.textContent = (tab.title[0] || "?").toUpperCase();
      favEl.classList.remove("emoji");
    } else {
      favEl.textContent = "🌐";
      favEl.classList.add("emoji");
    }

    tab.el.classList.toggle("active", tab.id === state.activeId);
  }

  function updateNewTabBtn() {
    newTabBtn.disabled = state.tabs.length >= MAX_TABS;
  }

  /* ================= tab lifecycle ================= */
  function createTab(url) {
    if (state.tabs.length >= MAX_TABS) return null;

    const tab = {
      id: state.nextId++,
      title: "New Tab",
      url: null,
      history: [],
      index: -1,
      iframe: null,
      loading: false,
      el: null
    };

    state.tabs.push(tab);
    buildTabEl(tab);
    updateNewTabBtn();

    if (url) navigate(tab, url);
    activateTab(tab.id);

    return tab;
  }

  function closeTab(id) {
    const i = state.tabs.findIndex((t) => t.id === id);
    if (i === -1) return;

    const tab = state.tabs[i];
    if (tab.el) tab.el.remove();
    if (tab.iframe) tab.iframe.remove();

    state.tabs.splice(i, 1);
    updateNewTabBtn();

    if (state.tabs.length === 0) {
      createTab();
      return;
    }

    if (state.activeId === id) {
      const next = state.tabs[Math.min(i, state.tabs.length - 1)];
      activateTab(next.id);
    }
  }

  function activateTab(id) {
    const tab = state.tabs.find((t) => t.id === id);
    if (!tab) return;

    state.activeId = id;

    state.tabs.forEach((t) => {
      if (t.el) t.el.classList.toggle("active", t.id === id);
      if (t.iframe) t.iframe.hidden = t.id !== id;
    });

    if (tab.url) {
      startPage.hidden = true;
      fab.classList.add("show");
      urlInput.value = tab.url;
      lock.textContent = tab.url.startsWith("https://") ? "🔒" : "🔓";
    } else {
      startPage.hidden = false;
      fab.classList.remove("show");
      urlInput.value = "";
      lock.textContent = "🔍";
    }

    if (tab.loading) startLoading(); else stopLoading();
    updateNav();
  }

  /* ================= navigation ================= */
  function navigate(tab, input, push = true) {
    if (!tab) return;
    const url = toUrl(input);
    if (!url) return;

    if (push) {
      tab.history = tab.history.slice(0, tab.index + 1);
      tab.history.push(url);
      tab.index = tab.history.length - 1;
    }
    render(tab, url);
  }

  // Direct navigation — bypasses URL parsing. Used for internal pages like credits.svg.
  function navigateTo(tab, url) {
    if (!tab || !url) return;
    tab.history = tab.history.slice(0, tab.index + 1);
    tab.history.push(url);
    tab.index = tab.history.length - 1;
    render(tab, url);
  }

  function render(tab, url) {
    if (!tab.iframe) {
      const f = createEl("iframe");
      f.title = "Browser content";
      f.hidden = true;
      f.addEventListener("load", () => {
        tab.loading = false;
        if (state.activeId === tab.id) stopLoading();
      });
      frames.appendChild(f);
      tab.iframe = f;
    }

    tab.url = url;
    tab.loading = true;
    tab.title = hostOf(url) || "Page";

    updateTabEl(tab);

    if (state.activeId === tab.id) {
      startPage.hidden = true;
      fab.classList.add("show");
      urlInput.value = url;
      lock.textContent = url.startsWith("https://") ? "🔒" : "🔓";
      startLoading();
      updateNav();
    }

    tab.iframe.hidden = state.activeId !== tab.id;
    tab.iframe.src = url;
  }

  function goHome(tab) {
    if (!tab) return;

    tab.url = null;
    tab.title = "New Tab";
    tab.history = [];
    tab.index = -1;
    tab.loading = false;

    if (tab.iframe) {
      tab.iframe.src = "about:blank";
      tab.iframe.hidden = true;
    }

    updateTabEl(tab);

    if (state.activeId === tab.id) {
      startPage.hidden = false;
      fab.classList.remove("show");
      urlInput.value = "";
      lock.textContent = "🔍";
      stopLoading();
      updateNav();
      startInput.focus();
    }
  }

  function updateNav() {
    const tab = activeTab();
    backBtn.disabled   = !tab || tab.index <= 0;
    fwdBtn.disabled    = !tab || tab.index >= tab.history.length - 1;
    reloadBtn.disabled = !tab || !tab.url;
    openBtn.disabled   = !tab || !tab.url;
  }

  function openExternal() {
    const tab = activeTab();
    if (tab && tab.url) window.open(tab.url, "_blank", "noopener");
  }

  /* ================= events ================= */
  newTabBtn.addEventListener("click", () => createTab());

  omnibox.addEventListener("submit", (e) => {
    e.preventDefault();
    navigate(activeTab(), urlInput.value);
    urlInput.blur();
  });

  startForm.addEventListener("submit", (e) => {
    e.preventDefault();
    const v = startInput.value;
    if (!v.trim()) return;
    startInput.value = "";
    navigate(activeTab(), v);
  });

  urlInput.addEventListener("focus", () => urlInput.select());

  backBtn.addEventListener("click", () => {
    const tab = activeTab();
    if (!tab || tab.index <= 0) return;
    tab.index--;
    render(tab, tab.history[tab.index]);
  });

  fwdBtn.addEventListener("click", () => {
    const tab = activeTab();
    if (!tab || tab.index >= tab.history.length - 1) return;
    tab.index++;
    render(tab, tab.history[tab.index]);
  });

  reloadBtn.addEventListener("click", () => {
    const tab = activeTab();
    if (!tab || !tab.url) return;

    tab.loading = true;
    startLoading();

    try {
      tab.iframe.contentWindow.location.reload();
    } catch (err) {
      const u = tab.url;
      tab.iframe.src = "about:blank";
      setTimeout(() => { tab.iframe.src = u; }, 30);
    }
  });

  homeBtn.addEventListener("click", () => goHome(activeTab()));
  openBtn.addEventListener("click", openExternal);
  fab.addEventListener("click", openExternal);

  // Credits — loads credits.svg into the current tab's iframe
  creditsBtn.addEventListener("click", () => {
    navigateTo(activeTab(), CREDITS_URL);
  });

  /* keyboard */
  document.addEventListener("keydown", (e) => {
    const mod = e.ctrlKey || e.metaKey;

    if (mod && e.key.toLowerCase() === "l") {
      e.preventDefault();
      urlInput.focus();
      urlInput.select();
      return;
    }

    if (e.altKey && e.key === "ArrowLeft") {
      e.preventDefault();
      backBtn.click();
      return;
    }

    if (e.altKey && e.key === "ArrowRight") {
      e.preventDefault();
      fwdBtn.click();
    }
  });

  /* ================= init ================= */
  createTab();
  startInput.focus();
})();
//
